// Writes docs/bot-templates.md: every customer-facing message in both languages (sample values), for Nabil to review.
// Usage: npx tsx src/scripts/print-templates.ts > docs/bot-templates.md
import { T, render, type TemplateName } from "../bot/arabic.js";
import { partsQuotedSettingSamples, sampleParams } from "../bot/template-samples.js";

const out: string[] = [
  "# Bot message templates",
  "",
  "Generated by `src/scripts/print-templates.ts` from `src/bot/arabic.ts` (object `T`, one entry per intent, comments there say when each is used).",
  "Sample values are fake. Prices appear only when the shop sets `priceQuotingEnabled` (see the per-setting section at the end). At most ONE message is sent per customer turn.",
  "Replies use the shop's `language` (default Arabic; `auto` follows the customer).",
  "",
];
for (const name of Object.keys(T) as TemplateName[]) {
  out.push(`## ${name}`, "");
  for (const lang of ["ar", "en"] as const) {
    const text = (render as (l: string, n: string, p: unknown) => string)(lang, name, sampleParams(lang));
    out.push(`**${lang}:**`, ...text.split("\n").map((l) => `> ${l}`), "");
  }
}
out.push("## partsQuoted by shop setting", "", "How the confirmed-parts reply changes with `showPartNumbers`, `stockDisplay`, `showAlternatives` and `priceQuotingEnabled` (`npm run shop -- set <id> key=value`).", "");
for (const lang of ["ar", "en"] as const) {
  for (const { title, params } of partsQuotedSettingSamples(lang)) {
    out.push(`**${lang}: ${title}**`, ...T.partsQuoted[lang](params).split("\n").map((l) => `> ${l}`), "");
  }
}
console.log(out.join("\n"));
